import { expect, test } from "@playwright/test";
import { getApiHeaders, getApiUrl } from "tests/helper/utils";
import { getEncounterId } from "tests/support/encounterId";
import { getFacilityId } from "tests/support/facilityId";
import { getPatientId } from "tests/support/patientId";

test.use({ storageState: "tests/.auth/user.json" });

for (const [layout, width] of [
  ["desktop", 1440],
  ["mobile", 390],
] as const) {
  test.describe(`Encounter navigation on ${layout}`, () => {
    test.use({ viewport: { width, height: 900 } });

    test.beforeEach(async ({ page }) => {
      await page.goto(
        `/facility/${getFacilityId()}/patient/${getPatientId()}/encounter/${getEncounterId()}/updates`,
      );
    });

    test("opens a section from the encounter navigation", async ({ page }) => {
      await test.step("Open Notes, including when it starts outside the mobile viewport", async () => {
        await page.getByRole("tab", { name: "Notes" }).click();

        await expect(page).toHaveURL(/\/notes$/);
        await expect(page.getByRole("tab", { name: "Notes" })).toHaveAttribute(
          "aria-selected",
          "true",
        );
        await expect(
          page.getByText("Discussions", { exact: true }),
        ).toBeVisible();
      });
    });

    test("keeps the chosen historical encounter when changing sections", async ({
      page,
      request,
    }) => {
      const response = await request.get(
        `${getApiUrl()}/api/v1/encounter/?patient=${getPatientId()}&limit=14`,
        { headers: getApiHeaders() },
      );
      expect(response.ok()).toBeTruthy();
      const encounters: { results: { id: string }[] } = await response.json();
      test.skip(
        !encounters.results.some(({ id }) => id !== getEncounterId()),
        "The patient fixture needs another encounter to exercise history selection",
      );

      await test.step("Choose another encounter from history", async () => {
        await page.getByRole("button", { name: /Encounter History/i }).click();
        const history = page.getByRole("dialog");
        await history.getByRole("button", { pressed: false }).first().click();
        await expect(history).not.toBeVisible();
        await expect(page).toHaveURL(/selectedEncounter=/);
      });

      const selectedEncounter = new URL(page.url()).searchParams.get(
        "selectedEncounter",
      );
      expect(selectedEncounter).not.toBe(getEncounterId());

      await test.step("Keep the selected encounter while opening Notes", async () => {
        await page.getByRole("tab", { name: "Notes" }).click();
        await expect(page).toHaveURL(
          (url) =>
            url.pathname.endsWith("/notes") &&
            url.searchParams.get("selectedEncounter") === selectedEncounter,
        );
        await expect(
          page.getByText("Discussions", { exact: true }),
        ).toBeVisible();
      });
    });
  });
}
