};

export function QuickAction({
  icon,
  title,
  actionId,
  href,
  basePath,
  onClick,
  hidden,
  ...props
}: {
  icon: React.ReactNode;
  title: string;
  actionId?: string;
  href?: string;
  basePath?: string;
  onClick?: () => void;
  hidden?: boolean;
} & React.ComponentProps<"button">) {
  const className = cn(
    "flex-1 flex flex-row md:flex-col gap-1.25 p-1 pb-2 rounded-lg shadow bg-white",
    hidden && "hidden",
  );

  if (href) {
    return (
      <Link basePath={basePath} href={href} className={className}>
        <QuickActionContent icon={icon} title={title} actionId={actionId} />
      </Link>
    );
  }

  return (
    <button className={className} {...props} onClick={onClick}>
      <QuickActionContent icon={icon} title={title} actionId={actionId} />
    </button>
  );
}

const QuickActionContent = ({
  icon,
  title,
  actionId,
}: {
  icon: React.ReactNode;
  title: string;
  actionId?: string;
}) => {
  return (
    <>
      <div className="relative flex md:py-3 py-0 rounded-t-md rounded-b-lg md:bg-gray-100 bg-white">
        {actionId && <ShortcutBadge actionId={actionId} position="top-right" />}
        <div className="rounded-xl bg-white md:shadow shadow-none mx-auto items-center flex p-2">
          {icon}
        </div>
      </div>
      <div className="flex items-center gap-1 justify-center">
        <span className="text-sm font-semibold">{title}</span>
      </div>
    </>
  );
};
import { type LucideIcon } from "lucide-react";
import { useEffect } from "react";
import { useTranslation } from "react-i18next";

import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

import PageTitle from "@/components/Common/PageHeadTitle";

import useBreakpoints from "@/hooks/useBreakpoints";
import EncounterHistorySelector from "@/pages/Encounters/EncounterHistorySelector";
import { ShortcutBadge } from "@/Utils/keyboardShortcutComponents";

export interface EncounterTab {
  label: string;
  icon: LucideIcon;
  component: React.ReactNode;
  shortcutId?: string;
  visible?: boolean;
}

interface Props {
  tabs: Record<string, EncounterTab>;
  currentTab: string;
  onTabChange: (tab: string) => void;
}

export default function EncounterNavigation({
  tabs,
  currentTab,
  onTabChange,
}: Props) {
  const { t } = useTranslation();
  const orientation = useBreakpoints<"horizontal" | "vertical">({
    default: "horizontal",
    lg: "vertical",
  });
  const visibleTabs = Object.entries(tabs).filter(
    ([, tab]) => tab.visible !== false,
  );

  useEffect(() => {
    if (tabs[currentTab]?.visible === false && visibleTabs.length) {
      onTabChange(visibleTabs[0][0]);
    }
  }, [currentTab, tabs, visibleTabs, onTabChange]);

  return (
    <Tabs
      value={currentTab}
      onValueChange={onTabChange}
      orientation={orientation}
      className="min-w-0 gap-4 lg:flex-row"
    >
      <div className="min-w-0 shrink-0 space-y-4 lg:w-60 lg:max-h-[calc(100vh-14rem-var(--encounter-header-offset))] lg:overflow-y-auto">
        <EncounterHistorySelector />
        <TabsList
          aria-label={t("encounter_navigation")}
          className="h-auto w-full justify-start gap-1 overflow-x-auto rounded-none bg-transparent p-0 lg:flex-col lg:items-stretch lg:overflow-x-hidden"
        >
          {visibleTabs.map(([key, { label, icon: Icon, shortcutId }]) => (
            <TabsTrigger
              key={key}
              value={key}
              onClick={() => onTabChange(key)}
              className="group h-auto min-h-11 shrink-0 justify-start gap-3 rounded-lg border border-transparent px-3 py-2.5 text-sm font-medium text-gray-700 hover:bg-gray-100 hover:text-gray-950 data-[state=active]:border-gray-200 data-[state=active]:bg-gray-200/60 data-[state=active]:font-semibold data-[state=active]:text-gray-950 data-[state=active]:shadow-none lg:w-full"
            >
              <Icon
                aria-hidden="true"
                className="size-4 text-gray-500 group-data-[state=active]:text-gray-950"
                strokeWidth={1.75}
              />
              {label}
              {shortcutId && (
                <ShortcutBadge
                  actionId={shortcutId}
                  className="ml-auto"
                  alwaysShow={false}
                />
              )}
            </TabsTrigger>
          ))}
        </TabsList>
      </div>
      {visibleTabs.map(([key, tab]) => (
        <TabsContent
          key={key}
          value={key}
          className="@container min-w-0 overflow-x-auto overflow-y-hidden lg:h-[calc(100vh-14rem-var(--encounter-header-offset))] lg:overflow-y-auto"
        >
          <PageTitle title={tab.label} />
          {tab.component}
        </TabsContent>
      ))}
    </Tabs>
  );
}
import {
  PatientDeceasedInfo,
  PatientHeader,
} from "@/components/Patient/PatientHeader";
import { Button, buttonVariants } from "@/components/ui/button";
import { format } from "date-fns";
import {
  Blocks,
  ChartLine,
  Eye,
  File,
  FileCheck,
  FileText,
  Folder,
  ListChecks,
  MessageCircle,
  Monitor,
  PanelsTopLeft,
  Pill,
} from "lucide-react";
import { useEffect, useState } from "react";

import Loading from "@/components/Common/Loading";
import Page from "@/components/Common/Page";
import { EncounterCommandDialog } from "@/components/Encounter/EncounterCommandDialog";
import ErrorPage from "@/components/ErrorPages/DefaultErrorPage";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { useShortcutSubContext } from "@/context/ShortcutContext";
import { useCareAppTabs } from "@/hooks/useCareApps";
import { useSidebarAutoCollapse } from "@/hooks/useSidebarAutoCollapse";
import { cn } from "@/lib/utils";
import EncounterNavigation, {
  EncounterTab,
} from "@/pages/Encounters/EncounterNavigation";
import { EncounterConsentsTab } from "@/pages/Encounters/tabs/consents";
import { EncounterDevicesTab } from "@/pages/Encounters/tabs/devices";
import { EncounterFilesTab } from "@/pages/Encounters/tabs/files";
import { EncounterMedicinesTab } from "@/pages/Encounters/tabs/medicines";
import { EncounterObservationsTab } from "@/pages/Encounters/tabs/observations";
import { EncounterOverviewTab } from "@/pages/Encounters/tabs/overview";
import { EncounterPlotsTab } from "@/pages/Encounters/tabs/plots";
import { EncounterResponsesTab } from "@/pages/Encounters/tabs/responses";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import { PLUGIN_Component } from "@/PluginEngine";
import {
  ENCOUNTER_STATUS_COLORS,
  EncounterRead,
} from "@/types/emr/encounter/encounter";
import { PatientRead } from "@/types/emr/patient/patient";
import { LocationTypeIcons } from "@/types/location/location";
import { ShortcutBadge } from "@/Utils/keyboardShortcutComponents";
import { entriesOf, goBack } from "@/Utils/utils";
import { navigate } from "raviger";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import { AppointmentEncounterHeader } from "./AppointmentEncounterHeader";
import { EncounterDiagnosticReportsTab } from "./tabs/diagnostic-reports";
import { EncounterNotesTab } from "./tabs/notes";
import { EncounterServiceRequestTab } from "./tabs/service-requests";

export interface PluginEncounterTabProps {
  encounter: EncounterRead;
  patient: PatientRead;
}

interface Props {
  tab?: string;
}

export const EncounterShow = (props: Props) => {
  const {
    facilityId,
    primaryEncounter,
    selectedEncounter,
    isSelectedEncounterLoading,
    primaryEncounterId,
    selectedEncounterId,
    isPrimaryEncounterLoading,
    patientId,
    patient,
    isPatientLoading,
    canWritePrimaryEncounter,
    canReadClinicalData,
    canReadSelectedEncounter,
  } = useEncounter();

  useSidebarAutoCollapse();
  const [actionsOpen, setActionsOpen] = useState(false);
  useShortcutSubContext("encounter");

  const { t } = useTranslation();
  const pluginTabs = useCareAppTabs<PluginEncounterTabProps>("encounterTabs");

  const canAccess = canReadClinicalData || canReadSelectedEncounter;
  const hasToken = primaryEncounter?.appointment?.token;
  // const isEncounterActive =
  //   primaryEncounter?.appointment?.id &&
  //   !inactiveEncounterStatus.includes(primaryEncounter?.status ?? "");

  const hasAppointmentId = primaryEncounter?.appointment?.id;

  // Header is shown either when token is present or encounter is active and has an appointment
  const canViewAppointmentEncounterHeader = hasToken || hasAppointmentId;

  useEffect(() => {
    if (!isPrimaryEncounterLoading && !isPatientLoading && !canAccess) {
      toast.error(t("permission_denied_encounter"));
      goBack("/");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isPrimaryEncounterLoading, isPatientLoading]);

  if (
    isPrimaryEncounterLoading ||
    !primaryEncounter ||
    (!facilityId && !patient)
  ) {
    return <Loading />;
  }

  if (!patient) {
    return <Loading />;
  }

  const tabs: Record<string, EncounterTab> = {
    updates: {
      icon: PanelsTopLeft,
      label: t(`ENCOUNTER_TAB__updates`),
      component: <EncounterOverviewTab />,
      shortcutId: "encounter-overview",
    },
    responses: {
      icon: MessageCircle,
      label: t(`ENCOUNTER_TAB__qnr_responses`),
      visible: canReadClinicalData,
      component: (
        <EncounterResponsesTab
          patientId={patientId}
          encounterId={selectedEncounterId}
          canAccess={canAccess}
        />
      ),
      shortcutId: "responses",
    },
    observations: {
      icon: Eye,
      label: t(`ENCOUNTER_TAB__observations`),
      visible: canReadClinicalData,
      component: <EncounterObservationsTab />,
      shortcutId: "observations",
    },
    medicines: {
      icon: Pill,
      label: t("medications"),
      visible: canReadClinicalData,
      component: <EncounterMedicinesTab />,
      shortcutId: "medicines",
    },
    service_requests: {
      icon: ListChecks,
      label: t(`ENCOUNTER_TAB__service_requests`),
      visible: canReadClinicalData,
      component: <EncounterServiceRequestTab />,
      shortcutId: "service-requests",
    },
    diagnostic_reports: {
      icon: FileText,
      label: t(`ENCOUNTER_TAB__diagnostic_reports`),
      visible: canReadClinicalData,
      component: <EncounterDiagnosticReportsTab />,
      shortcutId: "diagnostic-reports",
    },
    plots: {
      icon: ChartLine,
      label: t(`ENCOUNTER_TAB__plots`),
      visible: canReadClinicalData,
      component: <EncounterPlotsTab />,
      shortcutId: "plots",
    },
    files: {
      icon: Folder,
      label: t(`ENCOUNTER_TAB__files`),
      visible: canReadClinicalData,
      component: <EncounterFilesTab />,
      shortcutId: "files",
    },
    notes: {
      icon: File,
      label: t(`ENCOUNTER_TAB__notes`),
      visible: canReadClinicalData,
      component: <EncounterNotesTab />,
      shortcutId: "notes",
    },
    devices: {
      icon: Monitor,
      label: t(`ENCOUNTER_TAB__devices`),
      component: <EncounterDevicesTab />,
      shortcutId: "devices",
    },
    consents: {
      icon: FileCheck,
      label: t(`ENCOUNTER_TAB__consents`),
      component: <EncounterConsentsTab />,
      shortcutId: "consents",
    },

    ...Object.fromEntries(
      entriesOf(pluginTabs).map(([key, Component]) => [
        key,
        {
          label: t(`ENCOUNTER_TAB__${key}`),
          icon: Blocks,
          component: (
            <Component encounter={selectedEncounter!} patient={patient!} />
          ),
        },
      ]),
    ),
  };

  if (!props.tab || !Object.keys(tabs).includes(props.tab)) {
    return <ErrorPage />;
  }

  return (
    <Page
      title={t("encounter")}
      className="block md:px-1 -mt-4"
      hideTitleOnPage
      style={
        {
          "--encounter-header-offset": canViewAppointmentEncounterHeader
            ? "3rem"
            : "0rem",
        } as React.CSSProperties
      }
    >
      {primaryEncounter.appointment && canViewAppointmentEncounterHeader && (
        <div className="flex items-center justify-center -mt-2 mb-2">
          <AppointmentEncounterHeader
            canWritePrimaryEncounter={canWritePrimaryEncounter}
            appointment={primaryEncounter.appointment}
            encounter={primaryEncounter}
          />
        </div>
      )}

      <div className="flex flex-col gap-2">
        <Card className="bg-white shadow-sm border-none rounded-sm p-2 md:p-4 flex flex-col md:flex-row md:justify-between md:items-center gap-4">
          <PatientHeader
            patient={patient}
            facilityId={facilityId}
            className="flex-1 p-0 bg-transparent shadow-none"
          />
          {selectedEncounter && (
            <div className="flex max-md:flex-col items-end justify-center gap-4">
              <div className="w-full md:w-auto">
                <PLUGIN_Component
                  __name="PatientInfoCardQuickActions"
                  encounter={selectedEncounter}
                  className={cn(
                    buttonVariants({ variant: "primary_gradient" }),
                    "text-base font-semibold rounded-md w-full md:w-auto",
                  )}
                />
              </div>

              <EncounterCommandDialog
                encounter={selectedEncounter}
                open={actionsOpen}
                onOpenChange={setActionsOpen}
                trigger={
                  <Button
                    variant="primary_gradient"
                    onClick={() => setActionsOpen(true)}
                    className="text-base font-semibold rounded-md w-full md:w-auto"
                  >
                    {t("encounter_actions")}
                    <ShortcutBadge
                      actionId="open-command-dialog"
                      className="shrink-0"
                    />
                  </Button>
                }
              />
            </div>
          )}
        </Card>
        <PatientDeceasedInfo patient={patient} />
      </div>
      <div className="mt-4 flex min-w-0 flex-col gap-4">
        <div className="rounded-lg border border-gray-200 bg-white p-3">
          {isSelectedEncounterLoading ? (
            <Skeleton className="h-10 w-full max-w-md" />
          ) : (
            selectedEncounter && (
              <div className="flex flex-wrap gap-2 items-center">
                <h4 className="font-bold">
                  {t(`encounter_class__${selectedEncounter?.encounter_class}`)}
                </h4>
                <div className="text-sm text-gray-700 space-x-2">
                  {primaryEncounterId !== selectedEncounterId && (
                    <>
                      <span>{selectedEncounter?.facility.name}</span>
                      <span>|</span>
                    </>
                  )}

                  {selectedEncounter.current_location && (
                    <>
                      <span className="inline-flex items-center gap-1">
                        {(() => {
                          const LocationIcon =
                            LocationTypeIcons[
                              selectedEncounter.current_location.form
                            ];
                          return <LocationIcon className="size-3" />;
                        })()}
                        {selectedEncounter.current_location.name}
                      </span>
                      <span>|</span>
                    </>
                  )}

                  <span className="whitespace-nowrap">
                    {selectedEncounter.period.start && (
                      <span>
                        {format(
                          new Date(selectedEncounter.period.start!),
                          "dd MMM",
                        )}
                      </span>
                    )}
                    {selectedEncounter.period.end &&
                      selectedEncounter.period.start && <span>{" - "}</span>}
                    {selectedEncounter.period.end ? (
                      <span>
                        {format(
                          new Date(selectedEncounter.period.end),
                          "dd MMM",
                        )}
                      </span>
                    ) : (
                      <span>
                        {" - "}
                        {t("ongoing")}
                      </span>
                    )}
                  </span>
                </div>

                <Badge
                  variant={ENCOUNTER_STATUS_COLORS[selectedEncounter.status]}
                  size="sm"
                  className="whitespace-nowrap"
                >
                  {t(`encounter_status__${selectedEncounter.status}`)}
                </Badge>
              </div>
            )
          )}
        </div>

        <EncounterNavigation
          tabs={tabs}
          currentTab={props.tab}
          onTabChange={(tab) =>
            navigate(tab, {
              query:
                primaryEncounterId !== selectedEncounterId
                  ? { selectedEncounter: selectedEncounterId }
                  : undefined,
            })
          }
        />
      </div>
    </Page>
  );
};

