    ...Object.fromEntries(
      entriesOf(pluginTabs).map(([key, Component]) => [
        key,
        {
          label: t(`ENCOUNTER_TAB__${key}`),
          icon: Blocks,
          component: (
            <Component encounter={selectedEncounter!} patient={patient!} />
