import { format } from "date-fns";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";

import {
  ENCOUNTER_STATUS_COLORS,
  EncounterRead,
} from "@/types/emr/encounter/encounter";

interface Props {
  encounter?: EncounterRead;
  isLoading: boolean;
}

export default function EncounterDetailsHeader({
  encounter,
  isLoading,
}: Props) {
  const { t } = useTranslation();

  return (
    <div className="rounded-xl border border-gray-200 bg-white px-3 py-3 sm:px-4">
      {isLoading ? (
        <Skeleton className="h-9 w-full max-w-md" />
      ) : encounter ? (
        <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
          <span
            aria-hidden="true"
            className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-primary-50 text-xs font-bold text-primary-700"
          >
            {t(`encounter_class_short__${encounter.encounter_class}`)}
          </span>
          <span className="text-base font-semibold text-gray-950">
            {t(`encounter_class__${encounter.encounter_class}`)}
          </span>
          <div className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-1 text-sm text-gray-600">
            <span className="wrap-anywhere">{encounter.facility.name}</span>
            {encounter.current_location && (
              <>
                <span aria-hidden="true" className="text-gray-300">
                  ·
                </span>
                <span className="wrap-anywhere">
                  {encounter.current_location.name}
                </span>
              </>
            )}
            <span aria-hidden="true" className="text-gray-300">
              ·
            </span>
            <span className="whitespace-nowrap">
              {encounter.period.start &&
                format(new Date(encounter.period.start), "dd MMM yyyy")}
              {encounter.period.start && " – "}
              {encounter.period.end
                ? format(new Date(encounter.period.end), "dd MMM yyyy")
                : t("ongoing")}
            </span>
          </div>
          <Badge
            variant={ENCOUNTER_STATUS_COLORS[encounter.status]}
            size="sm"
            className="sm:ml-auto"
          >
            {t(`encounter_status__${encounter.status}`)}
          </Badge>
        </div>
      ) : null}
    </div>
  );
}
import { AllergyIcon } from "@/CAREUI/icons/CustomIcons";

import { BLOOD_GROUP_CHOICES } from "@/common/constants";
import { Avatar } from "@/components/Common/Avatar";
import { PatientAge } from "@/components/Patient/PatientAge";
import { PatientInfoHoverCard } from "@/components/Patient/PatientInfoHoverCard";
import { Badge } from "@/components/ui/badge";
import { Drawer, DrawerContent, DrawerTrigger } from "@/components/ui/drawer";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import {
  BloodGroupChoices,
  PatientListRead,
  PatientRead,
  PublicPatientRead,
} from "@/types/emr/patient/patient";
import { ChevronDown, DropletIcon, PanelBottomOpen } from "lucide-react";
import { useTranslation } from "react-i18next";

/** Blood group's short display text (e.g. "A+"); undefined when unset/unknown. */
function shortBloodGroup(bloodGroup?: BloodGroupChoices) {
  return bloodGroup === BloodGroupChoices.Unknown
    ? undefined
    : BLOOD_GROUP_CHOICES.find((choice) => choice.id === bloodGroup)?.text;
}

interface PatientHoverCardProps {
  patient: PublicPatientRead | PatientListRead | PatientRead;
  facilityId?: string;
  disabled?: boolean;
  compact?: { allergiesCount: number };
  presentation?: "default" | "encounter";
}

export function PatientHoverCard({
  patient,
  facilityId,
  disabled = false,
  compact,
  presentation = "default",
}: PatientHoverCardProps) {
  return (
    <>
      {/* Mobile Drawer */}
      <Drawer>
        <DrawerTrigger
          disabled={disabled}
          className={cn(
            "lg:hidden focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
            compact && "block w-full",
            presentation === "encounter" && "min-w-0 max-w-full text-left",
          )}
