      headers: getApiHeaders(),
      data: {
        patient: patientId,
        facility: getFacilityId(),
        status: "completed",
        encounter_class: "amb",
        period: { start: yesterday, end: yesterday },
        priority: "routine",
        organizations: [],
      },
