# React Components Instructions

## Import Path Conventions
- Use path aliases: `@/components/`, `@/types/`, `@/lib/`, `@/pages/`
- Import order: External packages → `@/components/ui/` → `@/components/` → `@/CAREUI/` → `@/types/` → `@/lib/` → relative imports
- Use named exports from `lucide-react` for icons (e.g., `import { SettingsIcon } from "lucide-react"`)
- Import `useTranslation` from `react-i18next` for internationalization

## Component Architecture Patterns
- Healthcare domain: Feature-based organization - Components grouped by Patient/, Facility/, Medication/, etc.
- React 19.1.1 hooks: Functional components only - Use React 19.1.1 hooks pattern
- TypeScript interfaces: Props interfaces - Always define PatientInfoCardProps, etc.
- Handle prefix: Event handlers - handleSubmit, handleTagsUpdate, handlePatientSelect

## UI Component System
- shadcn/ui components: Primary UI - Button, Card, Badge, etc. from `@/components/ui/`
- Healthcare-specific: CAREUI custom - Calendar, WeekdayCheckbox, Zoom from `@/CAREUI/`
- Button variants: Use `buttonVariants` from `@/components/ui/button` with CVA patterns
- Card structure: Follow `<Card><CardHeader>` pattern for consistent layouts

## Healthcare-Specific Patterns
- Patient data: Use `PatientRead` type from `@/types/emr/patient/patient`
- Tag system: Implement `TagAssignmentSheet` with `TagEntityType` for patient/facility tags
- Hover cards: Use `PatientHoverCard` for patient info overlays
- Badge usage: Display patient status, facility capacity, medication dosage with color variants

## Styling with Tailwind CSS 4.1.3
- Class variance authority: Use `cva()` for variant-based component styling
- Utility function: Use `cn()` from `@/lib/utils` for conditional classes
- Color system: Follow primary-700, gray-900, red-500 pattern with dark mode variants
- Shadow system: Use shadow-sm, shadow-xs for elevation
- Focus states: Include `focus-visible:ring-1` and `focus-visible:outline-hidden`

## State Management Integration
- Server state: React Query - Use `@tanstack/react-query` for facility data, patient records
- UI state: Local state - useState for UI state, useCallback for event handlers
- Controlled inputs: Form state - Handle controlled inputs with proper TypeScript typing
- Async operations: Loading states - Implement loading, error, and success states

## Internationalization (i18n)
- Translation hook: Use `const { t } = useTranslation()` pattern
- Text content: Wrap all user-facing text in `t("key.path")`
- Healthcare terminology: Use consistent medical term translations
- Date formatting: Use `date-fns` with locale support for medical timestamps

## Accessibility for Healthcare
- ARIA labels: Critical for medical data (patient names, vital signs, medication alerts)
- Keyboard navigation: Essential for clinical workflows and emergency situations
- Screen reader support: Proper heading hierarchy for medical records
- Color contrast: Meet WCAG AA standards for clinical environmentsimport { useInfiniteQuery } from "@tanstack/react-query";
import { format } from "date-fns";
import {
  BeakerIcon,
  CookingPotIcon,
  HeartPulseIcon,
  History,
  LeafIcon,
} from "lucide-react";
import { Link, usePath } from "raviger";
import { ReactNode } from "react";
import { useTranslation } from "react-i18next";

import { Button } from "@/components/ui/button";

import { TableSkeleton } from "@/components/Common/SkeletonLoading";
import EmptyState from "@/components/Patient/Common/EmptyState";
import { EncounterAccordionLayout } from "@/components/Patient/EncounterAccordionLayout";

import query from "@/Utils/request/query";
import { PaginatedResponse } from "@/Utils/request/types";
import { useCurrentFacilitySilently } from "@/pages/Facility/utils/useCurrentFacility";
import {
  AllergyCategory,
  AllergyIntolerance,
} from "@/types/emr/allergyIntolerance/allergyIntolerance";
import allergyIntoleranceApi from "@/types/emr/allergyIntolerance/allergyIntoleranceApi";
import {
  completedEncounterStatus,
  EncounterStatus,
} from "@/types/emr/encounter/encounter";

import { AllergyTable } from "./AllergyTable";

interface AllergyListProps {
  facilityId?: string;
  patientId: string;
  encounterId?: string;
  className?: string;
  readOnly?: boolean;
  encounterStatus?: EncounterStatus;
  showTimeline?: boolean;
  showViewEncounter?: boolean;
}
interface GroupedAllergies {
  [year: string]: {
    [date: string]: AllergyIntolerance[];
  };
}

export const CATEGORY_ICONS: Record<AllergyCategory, ReactNode> = {
  food: <CookingPotIcon className="size-4" aria-label="Food allergy" />,
  medication: <BeakerIcon className="size-4" aria-label="Medication allergy" />,
  environment: (
    <LeafIcon className="size-4" aria-label="Environmental allergy" />
  ),
  biologic: <HeartPulseIcon className="size-4" aria-label="Biologic allergy" />,
};

export function AllergyList({
  patientId,
  encounterId,
  className = "",
  readOnly = false,
  encounterStatus,
  showTimeline = false,
  showViewEncounter = true,
}: AllergyListProps) {
  const { t } = useTranslation();

  const LIMIT = showTimeline ? 30 : 14;
  const { facilityId } = useCurrentFacilitySilently();
  const sourceUrl = usePath();
  const { data, isLoading, fetchNextPage, hasNextPage, isFetchingNextPage } =
    useInfiniteQuery({
      queryKey: ["infinite-allergies", patientId, encounterId, encounterStatus],
      queryFn: async ({ pageParam = 0, signal }) => {
        const response = await query(allergyIntoleranceApi.getAllergy, {
          pathParams: { patientId },
          queryParams: {
            encounter:
              encounterStatus &&
              completedEncounterStatus.includes(encounterStatus)
                ? encounterId
                : undefined,
            limit: LIMIT,
            offset: String(pageParam),
            exclude_verification_status: "entered_in_error",
          },
        })({ signal });
        return response as PaginatedResponse<AllergyIntolerance>;
      },
      initialPageParam: 0,
      getNextPageParam: (lastPage, allPages) => {
        const currentOffset = allPages.length * LIMIT;
        return currentOffset < lastPage.count ? currentOffset : null;
      },
    });

  const allergies = data?.pages.flatMap((page) => page.results) ?? [];

  if (isLoading) {
    return <TableSkeleton count={5} />;
  }

  if (!allergies?.length) {
    if (showTimeline) {
      return (
        <EmptyState
          title={t("no_allergies")}
          description={t("no_allergies_recorded_description")}
        />
      );
    }
    return null;
  }

  if (showTimeline) {
    const groupedByYear = allergies.reduce((acc, allergy) => {
      const dateStr = format(allergy.created_date, "dd MMMM, yyyy");
      const year = format(allergy.created_date, "yyyy");
      acc[year] ??= {};
      acc[year][dateStr] ??= [];
      acc[year][dateStr].push(allergy);
      return acc;
    }, {} as GroupedAllergies);

    return (
      <div className="space-y-8">
        {Object.entries(groupedByYear).map(([year, groupedByDate]) => {
          return (
            <div key={year}>
              <h2 className="text-sm font-medium text-indigo-700 border-y border-gray-300 py-2 w-fit pr-10">
                {year}
              </h2>
              <div className="border-l border-gray-300 pt-5 ml-4">
                {Object.entries(groupedByDate).map(([date, allergies]) => {
                  return (
                    <div key={date} className="pb-6">
                      <div className="flex items-start gap-4">
                        <div className="flex flex-col items-center h-full">
                          <div className="size-3 bg-yellow-200 ring-1 ring-yellow-500 rounded-full flex-shrink-0 -ml-1.5 mt-1"></div>
                        </div>

                        <div className="space-y-3 overflow-auto w-full">
                          <h3 className="text-sm font-medium text-indigo-700">
                            {format(date, "dd MMMM, yyyy")}
                          </h3>
                          <AllergyTable
                            patientId={patientId}
                            allergies={allergies}
                          />
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
        {hasNextPage && (
          <div className="flex justify-center">
            <Button
              variant="ghost"
              size="xs"
              onClick={() => fetchNextPage()}
              disabled={isFetchingNextPage}
            >
              {t("load_more")}
            </Button>
          </div>
        )}
      </div>
    );
  }

  return (
    <EncounterAccordionLayout
      title={t("allergies")}
      readOnly={readOnly}
      className={className}
      editLink={!readOnly ? "questionnaire/allergy_intolerance" : undefined}
      actionButton={
        <Button
          variant="ghost"
          size="icon"
          asChild
          className="hover:bg-transparent text-gray-500 hover:text-gray-500"
        >
          <Link
            href={
              facilityId
                ? `/facility/${facilityId}/patient/${patientId}/history/allergies?sourceUrl=${encodeURIComponent(sourceUrl ?? "")}`
                : `/patient/${patientId}/history/allergies?sourceUrl=${encodeURIComponent(sourceUrl ?? "")}`
            }
          >
            <History className="size-4" />
          </Link>
        </Button>
      }
    >
      <AllergyTable
        allergies={allergies}
        patientId={patientId}
        showViewEncounter={showViewEncounter}
      />
      {hasNextPage && (
        <div className="flex justify-center">
          <Button
            variant="ghost"
            size="xs"
            onClick={() => fetchNextPage()}
            disabled={isFetchingNextPage}
          >
            {t("load_more")}
          </Button>
        </div>
      )}
    </EncounterAccordionLayout>
  );
}
