            category: "encounter_diagnosis,chronic_condition",
            clinical_status: ACTIVE_DIAGNOSIS_CLINICAL_STATUS.join(","),
            exclude_verification_status: "entered_in_error",
            ...(encounterId ? { encounter: encounterId } : {}),
