import TagBadge from "@/components/Tags/TagBadge";
import { cn } from "@/lib/utils";
import {
  PatientListRead,
  PatientRead,
  PublicPatientRead,
} from "@/types/emr/patient/patient";
import { TagConfig } from "@/types/emr/tagConfig/tagConfig";
import { useTranslation } from "react-i18next";

interface PatientTagsDisplayProps {
  patient: PublicPatientRead | PatientListRead | PatientRead;
  showLabel?: boolean;
  className?: string;
}

export const PatientTagsDisplay = ({
  patient,
  showLabel = true,
  className,
}: PatientTagsDisplayProps) => {
  const { t } = useTranslation();

  const allTags: TagConfig[] = [];

  if ("instance_tags" in patient) {
    allTags.push(...patient.instance_tags);
  }

  if ("facility_tags" in patient && patient.facility_tags) {
    allTags.push(...patient.facility_tags);
  }

  if (allTags.length === 0) {
    return null;
  }

  return (
    <div
      className={cn(
        "flex flex-col gap-1 text-sm font-medium w-full",
        className,
      )}
    >
      {showLabel && <span className="text-gray-700">{t("patient_tags")}:</span>}
      <div className="flex flex-wrap gap-2 text-sm whitespace-nowrap">
        {allTags.map((tag) => (
          <TagBadge key={tag.id} tag={tag} hierarchyDisplay />
        ))}
      </div>
    </div>
  );
};
import * as AvatarPrimitive from "@radix-ui/react-avatar";
import React from "react";

import { cn } from "@/lib/utils";

// Subtle, professional color combinations that blend well with the UI
const colorPairs: Array<[string, string]> = [
  ["#E3F2FD", "#1565C0"], // Subtle Blue
  ["#E8F5E9", "#2E7D32"], // Subtle Green
  ["#FFF3E0", "#E65100"], // Subtle Orange
  ["#F3E5F5", "#6A1B9A"], // Subtle Purple
  ["#E1F5FE", "#0277BD"], // Subtle Light Blue
  ["#E0F2F1", "#00695C"], // Subtle Teal
  ["#FBE9E7", "#D84315"], // Subtle Deep Orange
  ["#F3E5F5", "#6A1B9A"], // Subtle Purple
  ["#E8EAF6", "#283593"], // Subtle Indigo
  ["#FFF8E1", "#FF8F00"], // Subtle Amber
  ["#FCE4EC", "#C2185B"], // Subtle Pink
  ["#EFEBE9", "#4E342E"], // Subtle Brown
];

const stringToIndex = (name: string): number => {
  return name.split("").reduce((acc, char) => acc + char.charCodeAt(0), 0);
};

const getColorPair = (name: string): [string, string] => {
  const index = stringToIndex(name) % colorPairs.length;
  return colorPairs[index];
};

const initials = (name: string): string => {
  return name
    .split(" ")
    .slice(0, 2)
    .map((word) => word.slice(0, 1))
    .join("")
    .toUpperCase();
};

function Avatar({
  colors: propColors,
  name,
  imageUrl,
  className,
  ...props
}: React.ComponentProps<typeof AvatarPrimitive.Root> & {
  colors?: [string, string];
  name: string;
  imageUrl?: string;
  className?: string;
}) {
  const [hasImageError, setHasImageError] = React.useState(false);

  const avatarText = name.match(/[a-zA-Z]+/g)?.join(" ");

  const [bgColor, textColor] =
    propColors ||
    (avatarText ? getColorPair(avatarText) : getColorPair("user"));

  const shouldShowFallback = !imageUrl || hasImageError;

  return (
    <AvatarPrimitive.Root
      data-slot="avatar"
      className={cn("aspect-square size-full rounded-md", className)}
      style={{
        background: bgColor,
      }}
      {...props}
    >
      <AvatarPrimitive.Image
        data-slot="avatar-image"
        src={imageUrl}
        alt={name}
        className={cn(
          "aspect-square size-full object-cover rounded-md",
          className,
        )}
        onLoadingStatusChange={(status) => {
          if (status === "error") setHasImageError(true);
          if (status === "loaded") setHasImageError(false);
        }}
      />
      <AvatarPrimitive.Fallback
        data-slot="avatar-fallback"
        className="flex h-full w-full select-none items-center justify-center text-center"
      >
        {shouldShowFallback && (
          <svg
            xmlns="http://www.w3.org/2000/svg"
            version="1.1"
            viewBox="0 0 100 100"
            className="aspect-square h-full w-full object-cover"
          >
            <text
              fill={textColor}
              fillOpacity="0.5"
              fontSize="50"
              fontWeight="900"
              x="50"
              y="54"
              textAnchor="middle"
              dominantBaseline="middle"
              alignmentBaseline="middle"
            >
              {avatarText ? initials(avatarText) : null}
            </text>
          </svg>
        )}
      </AvatarPrimitive.Fallback>
    </AvatarPrimitive.Root>
  );
}

Avatar.displayName = "Avatar";

export { Avatar };

