import { HeartPulse, Stethoscope } from "lucide-react";
import { Link } from "raviger";
import React from "react";
import { useTranslation } from "react-i18next";

import { buttonVariants } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import {
  AllergyIcon,
  HealthWorkerIcon,
  MedicineIcon,
  TestTubeIcon,
} from "@/CAREUI/icons/CustomIcons";

import { ShortcutBadge } from "@/Utils/keyboardShortcutComponents";

import { FormDialog } from "./FormsDialog";

export const QuickActions = (props: React.ComponentProps<"div">) => {
  const { t } = useTranslation();

  return (
    <div {...props} className={cn("flex flex-wrap gap-2", props.className)}>
      <QuickAction
        compact
        icon={<AllergyIcon className="text-red-700" />}
        title={t("add_allergy", { count: 1 })}
        actionId="add-allergy"
        href={`questionnaire/allergy_intolerance`}
      />
      <QuickAction
        compact
        icon={<TestTubeIcon className="text-pink-700 size-8" />}
        title={t("service_request")}
        actionId="add-service-request"
        href={`questionnaire/service_request`}
      />
      <QuickAction
        compact
        icon={<MedicineIcon className="text-blue-800 size-8" />}
        title={t("add_medication")}
        href={`questionnaire/medication_request`}
        actionId="add-medication-request"
      />
      <QuickAction
        compact
        icon={<HeartPulse className="text-orange-700 size-8" />}
        title={t("add_symptom")}
        href={`questionnaire/symptom`}
        actionId="add-symptoms"
        hidden
      />
      <QuickAction
        compact
        icon={<Stethoscope className="text-purple-700 size-8" />}
        title={t("add_diagnosis")}
        href={`questionnaire/diagnosis`}
        actionId="add-diagnosis"
        hidden
      />
      <FormDialog
        subjectType="encounter"
        trigger={
          <QuickAction
            compact
            icon={<HealthWorkerIcon className="text-teal-700" />}
            title={t("forms")}
            actionId="add-questionnaire"
          />
        }
      />
    </div>
  );
};

export function QuickAction({
  icon,
  title,
  actionId,
  href,
  basePath,
  onClick,
  hidden,
  compact = false,
  ...props
}: {
  icon: React.ReactNode;
  title: string;
  actionId?: string;
  href?: string;
  basePath?: string;
  onClick?: () => void;
  hidden?: boolean;
  compact?: boolean;
} & React.ComponentProps<"button">) {
  const className = cn(
    compact
      ? cn(
          buttonVariants({ variant: "outline" }),
          "h-9 rounded-lg border-gray-200 px-3 font-medium text-gray-700 shadow-none",
        )
      : "flex-1 flex flex-row md:flex-col gap-1.25 p-1 pb-2 rounded-lg shadow bg-white",
    hidden && "hidden",
  );

  const content = compact ? (
    <>
      <span aria-hidden="true" className="[&_svg]:size-4">
        {icon}
      </span>
      {title}
      {actionId && <ShortcutBadge actionId={actionId} alwaysShow={false} />}
    </>
  ) : (
    <QuickActionContent icon={icon} title={title} actionId={actionId} />
  );

  if (href) {
    return (
      <Link
        basePath={basePath}
        href={href}
        className={className}
        aria-label={compact ? title : undefined}
      >
        {content}
      </Link>
    );
  }

  return (
    <button
      className={className}
      {...props}
      onClick={onClick}
      aria-label={compact ? title : undefined}
    >
      {content}
    </button>
  );
}

const QuickActionContent = ({
  icon,
  title,
  actionId,
}: {
  icon: React.ReactNode;
  title: string;
  actionId?: string;
}) => {
  return (
    <>
      <div className="relative flex md:py-3 py-0 rounded-t-md rounded-b-lg md:bg-gray-100 bg-white">
        {actionId && <ShortcutBadge actionId={actionId} position="top-right" />}
        <div className="rounded-xl bg-white md:shadow shadow-none mx-auto items-center flex p-2">
          {icon}
        </div>
      </div>
      <div className="flex items-center gap-1 justify-center">
        <span className="text-sm font-semibold">{title}</span>
      </div>
    </>
  );
};
import { useShortcutDisplay } from "@/context/ShortcutContext";
import { useKeyboardShortcuts } from "@/hooks/useKeyboardShortcuts";
import { cn } from "@/lib/utils";
import { cva, type VariantProps } from "class-variance-authority";

const keyboardShortcutBadgeVariants = cva(
  "h-5 min-w-5 flex justify-center px-1 rounded border font-medium text-xs",
  {
    variants: {
      variant: {
        default:
          "bg-linear-to-b from-white to-gray-200 border-gray-200 text-gray-700",
        primary: "border-gray-200/20 font-normal",
        classic_primary:
          "border-primary-900 font-normal bg-linear-to-b from-primary-600 to-primary-900",
        secondary: "bg-gray-50 text-gray-700",
      },
      position: {
        "top-right": "absolute top-1 right-1",
        "bottom-right": "absolute bottom-1 right-1",
        "top-left": "absolute top-1 left-1",
        "bottom-left": "absolute bottom-1 left-1",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

type KeyboardShortcutBadgeVariant = VariantProps<
  typeof keyboardShortcutBadgeVariants
>["variant"];

interface KeyboardShortcutBadgeProps {
  shortcut: string | undefined;
  className?: string;
  position?: "top-right" | "bottom-right" | "top-left" | "bottom-left";
  alwaysShow?: boolean;
  actionId?: string;
  variant?: KeyboardShortcutBadgeVariant;
}

/**
 * A reusable component that displays keyboard shortcuts as a small badge.
 * By default, no positioning is applied - use className or position prop for styling.
 */
export function KeyboardShortcutBadge({
  shortcut,
  className,
  position,
  alwaysShow = true,
  actionId,
  variant = "default",
}: KeyboardShortcutBadgeProps &
  VariantProps<typeof keyboardShortcutBadgeVariants>) {
  const { isOptionPressed } = useKeyboardShortcuts([], {});

  const shouldShowVisually = shortcut && (alwaysShow || isOptionPressed);

  return (
    <div
      data-shortcut-id={actionId}
      className={cn(
        keyboardShortcutBadgeVariants({ variant, position }),
        className,
        !shouldShowVisually && "hidden",
      )}
    >
      {shortcut}
    </div>
  );
}

/**
 * Simple component that takes an actionId and displays the keyboard shortcut badge
 * This is the simplest API - just pass the actionId and it handles everything
 * By default, no positioning is applied - use className or position prop for styling.
 *
 * This component automatically uses the current shortcut context hierarchy.
 */
export function ShortcutBadge({
  actionId,
  className,
  position,
  alwaysShow = true,
  variant = "default",
}: {
  actionId: string;
  className?: string;
  position?: "top-right" | "bottom-right" | "top-left" | "bottom-left";
  alwaysShow?: boolean;
  variant?: KeyboardShortcutBadgeVariant;
}) {
  const getShortcutDisplay = useShortcutDisplay();
  const { isOptionPressed } = useKeyboardShortcuts([], {});

  return (
    <KeyboardShortcutBadge
      shortcut={
        alwaysShow || isOptionPressed ? getShortcutDisplay(actionId) : undefined
      }
      className={className}
      position={position}
      alwaysShow={alwaysShow}
      actionId={actionId}
      variant={variant}
    />
  );
}

