import {
  ChevronDown,
  ClipboardList,
  HeartPulse,
  Microscope,
  Stethoscope,
} from "lucide-react";
import { Link } from "raviger";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";

import { Button, buttonVariants } from "@/components/ui/button";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { cn } from "@/lib/utils";

import { AllergyIcon, MedicineIcon } from "@/CAREUI/icons/CustomIcons";

import { ShortcutBadge } from "@/Utils/keyboardShortcutComponents";

import { FormDialog } from "./FormsDialog";

export const QuickActions = (props: React.ComponentProps<"div">) => {
  const { t } = useTranslation();
  const [expanded, setExpanded] = useState(false);

  return (
    <div {...props} className={cn("@container", props.className)}>
      <Collapsible
        open={expanded}
        onOpenChange={setExpanded}
        className="flex w-fit max-w-full items-start gap-1.5 rounded-xl border border-gray-300 bg-gray-100 p-1.5"
      >
        <CollapsibleTrigger asChild>
          <Button
            type="button"
            variant="ghost"
            className="h-11 w-8 shrink-0 self-center rounded-lg p-0 text-gray-600 hover:bg-gray-200 hover:text-gray-950"
            aria-label={expanded ? t("show_less") : t("more_actions")}
            title={expanded ? t("show_less") : t("more_actions")}
          >
            <ChevronDown
              aria-hidden="true"
              className={cn("transition-transform", expanded && "rotate-180")}
            />
          </Button>
        </CollapsibleTrigger>
        <div className="grid min-w-0 flex-1 grid-cols-2 gap-1.5 @min-[38rem]:grid-cols-[repeat(4,auto)]">
          <QuickAction
            compact
            icon={<AllergyIcon className="text-amber-700" />}
            title={t("allergy")}
            aria-label={t("add_allergy", { count: 1 })}
            actionId="add-allergy"
            href={`questionnaire/allergy_intolerance`}
          />
          <QuickAction
            compact
            icon={<Microscope className="text-pink-600" strokeWidth={1.5} />}
            title={t("service_request")}
            actionId="add-service-request"
            href={`questionnaire/service_request`}
          />
          <QuickAction
            compact
            icon={<MedicineIcon className="text-teal-700" />}
            title={t("medication")}
            aria-label={t("add_medication")}
            href={`questionnaire/medication_request`}
            actionId="add-medication-request"
          />
          <FormDialog
            subjectType="encounter"
            trigger={
              <QuickAction
                compact
                icon={
                  <ClipboardList className="text-teal-700" strokeWidth={1.5} />
                }
                title={t("forms")}
                actionId="add-questionnaire"
              />
            }
          />
          <CollapsibleContent className="col-span-full grid grid-cols-subgrid gap-1.5 data-[state=closed]:hidden">
            <QuickAction
              compact
              icon={
                <HeartPulse className="text-orange-700" strokeWidth={1.5} />
              }
              title={t("symptoms")}
              aria-label={t("add_symptom")}
              href="questionnaire/symptom"
              actionId="add-symptoms"
            />
            <QuickAction
              compact
              icon={
                <Stethoscope className="text-purple-700" strokeWidth={1.5} />
              }
              title={t("diagnosis")}
              aria-label={t("add_diagnosis")}
              href="questionnaire/diagnosis"
              actionId="add-diagnosis"
            />
          </CollapsibleContent>
        </div>
      </Collapsible>
    </div>
  );
};

export function QuickAction({
  icon,
  title,
  actionId,
  href,
  basePath,
  onClick,
  hidden,
  compact = false,
  ...props
}: {
  icon: React.ReactNode;
  title: string;
  actionId?: string;
  href?: string;
  basePath?: string;
  onClick?: () => void;
  hidden?: boolean;
  compact?: boolean;
} & React.ComponentProps<"button">) {
  const className = cn(
    compact
      ? cn(
          buttonVariants({ variant: "outline" }),
          "h-auto min-h-11 min-w-0 w-full justify-start gap-1.5 rounded-lg border-gray-200 bg-white px-2 py-2 text-left font-semibold text-gray-950 whitespace-normal shadow-xs transition-[background-color,border-color,box-shadow] hover:border-gray-300 hover:bg-white hover:shadow-sm active:bg-gray-50 active:shadow-none focus-visible:ring-2 focus-visible:ring-primary-600 focus-visible:ring-offset-2 [&_svg]:size-6",
        )
      : "flex-1 flex flex-row md:flex-col gap-1.25 p-1 pb-2 rounded-lg shadow bg-white",
    hidden && "hidden",
  );

  const content = compact ? (
    <>
      <span
        aria-hidden="true"
        className="flex size-6 shrink-0 items-center justify-center [&_svg]:size-6"
      >
        {icon}
      </span>
      <span className="min-w-0 flex-1 leading-5">{title}</span>
      {actionId && (
        <ShortcutBadge
          actionId={actionId}
          variant="secondary"
          className="h-5 min-w-5 shrink-0 items-center rounded-md border-gray-200 border-b-2 px-1 font-normal text-gray-600 shadow-xs"
        />
      )}
    </>
  ) : (
    <QuickActionContent icon={icon} title={title} actionId={actionId} />
  );

  if (href) {
    return (
      <Link
        basePath={basePath}
      }

      const hasOpenOverlay = document.querySelector(
        '[data-state="open"][data-slot="sheet-overlay"], [data-state="open"][data-slot="dialog-overlay"]',
      );
      if (hasOpenOverlay && contexts.includes("encounter")) {
        return;
      }

      // Guard against keyboard events without a key property, which can occur during component initialization or in certain browser edge cases.
      if (!event.key) return;

      const key = event.key.toLowerCase();
      const modifiedShortcut = Object.entries(
        categorizedShortcuts.modified,
      ).find(([keyCombo]) => matchesKeyCombo(keyCombo, event));

      if (modifiedShortcut) {
        const [, shortcut] = modifiedShortcut;
        const handler = handlers[shortcut.action];
        if (handler) {
          event.preventDefault();
          event.stopPropagation();
          handler();
          return;
        }
      }

      if (prefixActiveRef.current) {
        const currentPrefix = prefixActiveRef.current;
        const prefixShortcuts =
          categorizedShortcuts.prefixGroups[currentPrefix];

        if (prefixShortcuts) {
          const shortcut = prefixShortcuts[key];
          if (shortcut) {
            const handler = handlers[shortcut.action];
            if (handler) {
              event.preventDefault();
              event.stopPropagation();
              handler();
            }
          }
        }
        prefixActiveRef.current = null;
        setActivePrefix(null);
        return;
      }

      const availablePrefixes = Object.keys(categorizedShortcuts.prefixGroups);
      if (
        availablePrefixes.includes(key) &&
        !event.shiftKey &&
        !event.ctrlKey &&
        !event.metaKey &&
        !event.altKey
      ) {
        prefixActiveRef.current = key;
        setActivePrefix(key);
        event.preventDefault();
        return;
      }

      const directShortcut = categorizedShortcuts.direct[key];
      if (
        directShortcut &&
        !event.shiftKey &&
        !event.ctrlKey &&
        !event.metaKey &&
        !event.altKey
      ) {
        const handler = handlers[directShortcut.action];
        if (handler) {
          event.preventDefault();
          event.stopPropagation();
          handler();
        }
      }
    },
    [categorizedShortcuts, handlers, matchesKeyCombo, isOptionPressed],
  );

  const handleKeyUp = useCallback(
    (event: KeyboardEvent) => {
      // Track Option/Alt key state
      if (event.altKey !== isOptionPressed) {
        setIsOptionPressed(event.altKey);
      }
    },
    [isOptionPressed],
  );

  const handleWindowBlur = useCallback(() => {
    // Reset Option key state when window loses focus
    setIsOptionPressed(false);
  }, []);

  useEffect(() => {
    document.addEventListener("keydown", handleKeyDown);
    document.addEventListener("keyup", handleKeyUp);
    window.addEventListener("blur", handleWindowBlur);
    return () => {
      document.removeEventListener("keydown", handleKeyDown);
      document.removeEventListener("keyup", handleKeyUp);
      window.removeEventListener("blur", handleWindowBlur);
    };
  }, [handleKeyDown, handleKeyUp, handleWindowBlur]);

  return {
    shortcuts,
    activePrefix,
    isOptionPressed,
  };
}
import { createContext, useContext, useEffect, useMemo, useState } from "react";

import actionsJson from "@/config/keyboardShortcuts.json";
import { useIsMobile } from "@/hooks/use-mobile";
import {
  ShortcutHandlers,
  useKeyboardShortcuts,
} from "@/hooks/useKeyboardShortcuts";
import { FacilityAction } from "@/types/shortcuts";
import {
  formatKeyboardShortcut,
  shortcutActionHandler,
} from "@/Utils/keyboardShortcutUtils";
import { expandShortcutContext } from "@/Utils/shortcutUtils";

interface ShortcutContextType {
  /**
   * Whether the command dialog is open
   */
  commandDialogOpen: boolean;
  /**
   * Set the command dialog open state
   */
  setCommandDialogOpen: (open: boolean) => void;
  /**
   * Current shortcut sub-context (e.g., "appointment-detail", "patient-detail")
   */
  subContext?: string;
  /**
   * Set the current shortcut sub-context
   */
  setSubContext: (subContext?: string) => void;
  /**
   * Whether shortcuts should run even when input fields are focused
   */
  ignoreInputFields: boolean;
  /**
   * Set whether shortcuts should run even when input fields are focused
   */
  setIgnoreInputFields: (ignore: boolean) => void;
  /**
   * Get the display string for a shortcut action ID based on current context
   */
  getShortcutDisplay: (actionId: string) => string | undefined;
}

const ShortcutContext = createContext<ShortcutContextType | null>(null);

interface ShortcutProviderProps {
  children: React.ReactNode;
  /**
   * Whether shortcuts should run even when input fields are focused
   * @default false
   */
  ignoreInputFields?: boolean;
}

export function ShortcutProvider({
  children,
  ignoreInputFields: defaultIgnoreInputFields = false,
}: ShortcutProviderProps) {
  const [commandDialogOpen, setCommandDialogOpen] = useState(false);
  const [subContext, setSubContext] = useState<string | undefined>();
  const [ignoreInputFields, setIgnoreInputFields] = useState(
    defaultIgnoreInputFields,
  );
  const isMobile = useIsMobile();

  // Facility shortcuts logic (moved from useShortcutSubContext)
  const actions = useMemo((): FacilityAction[] => {
    const allContexts = expandShortcutContext(subContext || "");

    return [
      ...(subContext?.includes("-global") ? [] : ["global"]),
      ...allContexts,
    ]
      .map((context) => {
        const contextActions = actionsJson[context as keyof typeof actionsJson];

        if (!contextActions) return [];
        return contextActions.map((a) => ({
          id: a.action,
          handler: shortcutActionHandler(a.action),
        }));
      })
      .flat();
  }, [subContext]);

  const handlers = useMemo(() => {
    const handlersMap: ShortcutHandlers = {};

    actions.forEach((action) => {
      handlersMap[action.id] = () => {
        action.handler();
      };
    });

    handlersMap["show-shortcuts"] = () => setCommandDialogOpen(true);

    return handlersMap;
  }, [actions]);

  // Function to get shortcut display string for an action ID
  const getShortcutDisplay = useMemo(() => {
    return (actionId: string): string | undefined => {
      if (isMobile) {
        return undefined;
