export const QuickActions = (props: React.ComponentProps<"div">) => {
  const { t } = useTranslation();
  const [expanded, setExpanded] = useState(false);

  return (
    <div {...props} className={cn("@container", props.className)}>
      <Collapsible
        open={expanded}
        onOpenChange={setExpanded}
        className="flex w-fit max-w-full items-start gap-1.5 rounded-xl border border-gray-300 bg-gray-100 p-1.5"
      >
        <CollapsibleTrigger asChild>
          <Button
            type="button"
            variant="ghost"
            className="h-11 w-8 shrink-0 self-center rounded-lg p-0 text-gray-600 hover:bg-gray-200 hover:text-gray-950"
            aria-label={expanded ? t("show_less") : t("more_actions")}
            title={expanded ? t("show_less") : t("more_actions")}
            onKeyDown={(event) => {
              if (
                event.key === "Enter" &&
                !event.shiftKey &&
                !event.ctrlKey &&
                !event.metaKey &&
                !event.altKey
              ) {
                // Let Enter activate this button instead of the global shortcut.
                event.stopPropagation();
              }
            }}
          >
            <ChevronDown
              aria-hidden="true"
              className={cn("transition-transform", expanded && "rotate-180")}
            />
          </Button>
        </CollapsibleTrigger>
        <div className="grid min-w-0 flex-1 grid-cols-2 gap-1.5 @min-[38rem]:grid-cols-[repeat(4,auto)]">
