import { format } from "date-fns";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";

import {
  ENCOUNTER_STATUS_COLORS,
  EncounterRead,
} from "@/types/emr/encounter/encounter";

interface Props {
  encounter?: EncounterRead;
  isLoading: boolean;
}

export default function EncounterDetailsHeader({
  encounter,
  isLoading,
}: Props) {
  const { t } = useTranslation();

  return (
    <div className="rounded-xl border border-gray-200 bg-white px-3 py-2.5 sm:px-4">
      {isLoading ? (
        <Skeleton className="h-9 w-full max-w-md" />
      ) : encounter ? (
        <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
          <span
            aria-hidden="true"
            className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-primary-50 text-xs font-bold text-primary-700"
          >
            {t(`encounter_class_short__${encounter.encounter_class}`)}
          </span>
          <span className="text-base font-semibold text-gray-950">
            {t(`encounter_class__${encounter.encounter_class}`)}
          </span>
          <div className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-1 text-[15px] text-gray-600">
            <span className="wrap-anywhere">{encounter.facility.name}</span>
            {encounter.current_location && (
              <>
                <span aria-hidden="true" className="text-gray-300">
                  ·
                </span>
                <span className="wrap-anywhere">
                  {encounter.current_location.name}
                </span>
              </>
            )}
            <span aria-hidden="true" className="text-gray-300">
              ·
            </span>
            <span className="whitespace-nowrap">
              {encounter.period.start &&
                format(new Date(encounter.period.start), "dd MMM yyyy")}
              {encounter.period.start && " – "}
              {encounter.period.end
                ? format(new Date(encounter.period.end), "dd MMM yyyy")
                : t("ongoing")}
            </span>
          </div>
          <Badge
            variant={ENCOUNTER_STATUS_COLORS[encounter.status]}
            size="sm"
            className="sm:ml-auto"
          >
            {t(`encounter_status__${encounter.status}`)}
          </Badge>
        </div>
      ) : null}
    </div>
  );
}
  patient: PatientRead;
}

interface Props {
  tab?: string;
}

export const EncounterShow = (props: Props) => {
  const {
    facilityId,
    primaryEncounter,
    selectedEncounter,
    isSelectedEncounterLoading,
    primaryEncounterId,
    selectedEncounterId,
    isPrimaryEncounterLoading,
    patientId,
    patient,
    isPatientLoading,
    canWritePrimaryEncounter,
    canReadClinicalData,
    canReadSelectedEncounter,
  } = useEncounter();

  useSidebarAutoCollapse();
  const [actionsOpen, setActionsOpen] = useState(false);
  useShortcutSubContext("encounter");

  const { t } = useTranslation();
  const pluginTabs = useCareAppTabs<PluginEncounterTabProps>("encounterTabs");

  const canAccess = canReadClinicalData || canReadSelectedEncounter;
  const hasToken = primaryEncounter?.appointment?.token;
  // const isEncounterActive =
  //   primaryEncounter?.appointment?.id &&
  //   !inactiveEncounterStatus.includes(primaryEncounter?.status ?? "");

  const hasAppointmentId = primaryEncounter?.appointment?.id;

  // Header is shown either when token is present or encounter is active and has an appointment
  const canViewAppointmentEncounterHeader = hasToken || hasAppointmentId;

  useEffect(() => {
    if (!isPrimaryEncounterLoading && !isPatientLoading && !canAccess) {
      toast.error(t("permission_denied_encounter"));
      goBack("/");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isPrimaryEncounterLoading, isPatientLoading]);

  if (
    isPrimaryEncounterLoading ||
    !primaryEncounter ||
    (!facilityId && !patient)
  ) {
    return <Loading />;
  }

  if (!patient) {
    return <Loading />;
  }

  const tabs: Record<string, EncounterTab> = {
    updates: {
      icon: PanelsTopLeft,
      label: t(`ENCOUNTER_TAB__updates`),
                    />
                  </Button>
                }
              />
            </div>
          )}
          <PatientTagsDisplay
            patient={patient}
            className="order-2 min-w-0 flex-row flex-wrap items-baseline gap-x-2 gap-y-1 lg:order-3 lg:col-span-2 [&>span]:shrink-0 [&>span]:text-xs [&>span]:font-normal [&>span]:text-gray-500 [&>div]:min-w-0 [&>div]:flex-1 [&>div]:gap-1.5 [&_[data-slot=badge]]:max-w-full [&_[data-slot=badge]]:whitespace-normal [&_[data-slot=badge]]:wrap-anywhere"
          />
        </Card>
        <PatientDeceasedInfo patient={patient} />
      </div>
      <div className="mt-4 flex min-w-0 flex-col gap-4">
        <EncounterDetailsHeader
          encounter={selectedEncounter}
          isLoading={isSelectedEncounterLoading}
        />

        <EncounterNavigation
          tabs={tabs}
          currentTab={props.tab}
          onTabChange={(tab) =>
            navigate(tab, {
              query:
                primaryEncounterId !== selectedEncounterId
                  ? { selectedEncounter: selectedEncounterId }
                  : undefined,
            })
          }
        />
      </div>
    </Page>
  );
};
  patientId,
}: {
  children: React.ReactNode;
  encounterId: string;
  facilityId?: string;
  patientId: string;
}) {
  const [
    { selectedEncounter: selectedEncounterId = primaryEncounterId },
    setQParams,
  ] = useQueryParams();

  const { data: patient, isLoading: isPatientLoading } = useQuery({
    queryKey: ["patient", patientId, facilityId],
    queryFn: query(patientApi.get, {
      pathParams: { id: patientId },
      queryParams: { facility: facilityId },
      silent: true,
    }),
  });

  const { data: primaryEncounter, isLoading: isPrimaryEncounterLoading } =
    useQuery({
      queryKey: ["encounter", primaryEncounterId],
      queryFn: query(encounterApi.get, {
        pathParams: { id: primaryEncounterId },
        queryParams: facilityId
          ? { facility: facilityId }
          : { patient: patientId },
      }),
    });

  const { data: selectedEncounter, isLoading: isSelectedEncounterLoading } =
    useQuery({
      queryKey: ["encounter", selectedEncounterId],
      queryFn: query(encounterApi.get, {
        pathParams: { id: selectedEncounterId },
        queryParams: facilityId
          ? { facility: facilityId }
          : { patient: patientId },
      }),
    });

  const setSelectedEncounter = (encounterId: string | null) => {
    setQParams(
      { selectedEncounter: encounterId },
      { replace: false, overwrite: false },
    );
  };

  const { hasPermission } = usePermissions();

  const primaryEncounterPermissions = getPermissions(
    hasPermission,
    primaryEncounter?.permissions ?? [],
  );

  const selectedEncounterPermissions = getPermissions(
    hasPermission,
    selectedEncounter?.permissions ?? [],
  );

  const patientPermissions = getPermissions(
    hasPermission,
    patient?.permissions ?? [],
  );

  // User can access the selected encounter if they have read encounter
  const canReadSelectedEncounter =
    selectedEncounterPermissions.canReadEncounter;

  // User can access clinical data if they have canViewClinicalData permission or canViewEncounter permission
  const canReadClinicalData =
    patientPermissions.canViewClinicalData ||
    selectedEncounterPermissions.canReadEncounterClinicalData;

  // User can edit the selected encounter if it was accessed via facility scope, is the same as the primary encounter in view, and is active
  const canWriteSelectedEncounter =
    !!facilityId &&
    selectedEncounterId === primaryEncounterId &&
    !!selectedEncounter &&
    !inactiveEncounterStatus.includes(selectedEncounter.status);

  // User can restart the selected encounter if it was accessed via facility scope, is the same as the primary encounter in view, and is completed
  const canRestartSelectedEncounter =
    !!facilityId &&
    selectedEncounterId === primaryEncounterId &&
    !!selectedEncounter &&
    completedEncounterStatus.includes(selectedEncounter.status);

  // User can access the current encounter if they have canReadEncounter permission
  const canReadPrimaryEncounter = primaryEncounterPermissions.canReadEncounter;
  // User can edit the current encounter if it was accessed via facility scope and is active
  const canWritePrimaryEncounter =
    canReadPrimaryEncounter &&
    !!facilityId &&
    !!primaryEncounter &&
    !inactiveEncounterStatus.includes(primaryEncounter.status);

  // User can write clinical data if they have canViewClinicalData permission and can write the selected encounter
  const canWriteClinicalData = canReadClinicalData && canWriteSelectedEncounter;

  const [activeAction, setActiveAction] = useState<EncounterAction | null>(
    null,
  );
  const [completeEverything, setCompleteEverything] = useState(false);

