import { Search } from "lucide-react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import { useAppSidebar } from "@/components/ui/sidebar/app-sidebar-provider";
import { FacilitySwitcher } from "@/components/ui/sidebar/facility/facility-switcher";
import { OrganizationSwitcher } from "@/components/ui/sidebar/organization-switcher";
import { PatientSwitcher } from "@/components/ui/sidebar/patient-switcher";
import { ResponsibilitySwitcher } from "@/components/ui/sidebar/responsibility-switcher";
import { AppSidebarToggle } from "@/components/ui/sidebar/sidebar-toggle";

import { useRouteParams } from "@/hooks/useRouteParams";

import { CurrentUserRead } from "@/types/user/user";

interface WorkspaceHeaderProps {
  user?: CurrentUserRead;
  patient?: boolean;
  onSearch?: () => void;
}

export function WorkspaceHeader({
  user,
  patient,
  onSearch,
}: WorkspaceHeaderProps) {
  const { t } = useTranslation();
  const { innerWorkspace } = useAppSidebar();
  const { facilityId } = useRouteParams("/facility/:facilityId");
  const { organizationId } = useRouteParams("/organization/:organizationId");
  const { responsibilityId } = useRouteParams(
    "/responsibilities/:responsibilityId",
  );
  const facility = user?.facilities.find((item) => item.id === facilityId);
  const organization = user?.organizations.find(
    (item) => item.id === organizationId,
  );

  return (
    <header
      data-cui-app-header
      className={cn(
        "sticky top-0 z-10 flex shrink-0 items-center gap-3 border-b border-neutral-200 bg-white px-4 text-neutral-950",
        innerWorkspace ? "h-12" : "h-14 md:rounded-t-[14px]",
      )}
    >
      <AppSidebarToggle />
      <span aria-hidden="true" className="h-5 w-px shrink-0 bg-neutral-200" />
      <div className="min-w-0 max-w-[min(20rem,65vw)]">
        {patient ? (
          <PatientSwitcher />
        ) : responsibilityId ? (
          <ResponsibilitySwitcher selectedResponsibilityId={responsibilityId} />
        ) : organization ? (
          <OrganizationSwitcher
            organizations={user?.organizations ?? []}
            selectedOrganization={organization}
          />
        ) : facility ? (
          <FacilitySwitcher
            facilities={user?.facilities ?? []}
            selectedFacility={facility}
          />
        ) : (
          <span className="truncate text-sm font-medium">{t("care")}</span>
        )}
      </div>
      {onSearch && (
        <Button
          variant="outline"
          size="sm"
          onClick={onSearch}
          aria-label={t("search_page_actions")}
          className="ml-auto size-8 shrink-0 gap-2 rounded-lg border-neutral-300 bg-white p-0 text-neutral-500 shadow-sm hover:bg-neutral-100 focus-visible:ring-indigo-400 sm:h-9 sm:w-52 sm:justify-start sm:px-3"
        >
          <Search className="size-4" aria-hidden="true" />
          <span className="hidden sm:inline">{t("search_page_actions")}</span>
        </Button>
      )}
    </header>
  );
}
import { PanelLeft } from "lucide-react";
import { ComponentProps } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Button } from "@/components/ui/button";
import { useSidebar } from "@/components/ui/sidebar";
import { useAppSidebar } from "@/components/ui/sidebar/app-sidebar-provider";
import { TooltipComponent } from "@/components/ui/tooltip";
import careConfig from "@careConfig";

export function AppSidebarToggle({
  className,
  onClick,
  onMouseEnter,
  onMouseLeave,
  onBlur,
  ...props
}: ComponentProps<typeof Button>) {
  const { t } = useTranslation();
  const { isMobile, openMobile, setOpenMobile } = useSidebar();
  const {
    pinned,
    isOverlay,
    toggleSidebar,
    handleToggleMouseEnter,
    scheduleClose,
  } = useAppSidebar();
  const showLogo = isMobile ? !openMobile : !pinned;

  const button = (
    <Button
      type="button"
      variant="ghost"
      size="icon"
      data-sidebar="trigger"
      aria-label={t("toggle_sidebar")}
      aria-expanded={isMobile ? openMobile : pinned || isOverlay}
      className={cn(
        "relative -ml-1 size-7 shrink-0 text-neutral-700 after:absolute after:-inset-3 after:content-[''] hover:bg-neutral-200 hover:text-neutral-950 focus-visible:ring-2 focus-visible:ring-indigo-400",
        showLogo && "h-9 w-auto px-1",
        className,
      )}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented) return;
        if (isMobile) setOpenMobile(!openMobile);
        else toggleSidebar();
      }}
      onMouseEnter={(event) => {
        onMouseEnter?.(event);
        if (!event.defaultPrevented) handleToggleMouseEnter();
      }}
      onMouseLeave={(event) => {
        onMouseLeave?.(event);
        if (!event.defaultPrevented) scheduleClose();
      }}
      onBlur={(event) => {
        onBlur?.(event);
        if (!event.defaultPrevented) scheduleClose();
      }}
      {...props}
    >
      {showLogo ? (
        <img
          src={careConfig.mainLogo?.dark ?? "/images/care_logo.svg"}
          alt=""
          aria-hidden="true"
          draggable={false}
          className="h-9 w-auto max-w-28 shrink-0 object-contain"
        />
      ) : (
        <PanelLeft className="size-4" aria-hidden="true" />
      )}
    </Button>
  );

  if (isMobile) return button;

  return (
    <TooltipComponent content={t("toggle_sidebar")} side="left">
      {button}
    </TooltipComponent>
  );
}

