import { format } from "date-fns";
import { ArrowLeft, History, SquarePen } from "lucide-react";
import { Link } from "raviger";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Skeleton } from "@/components/ui/skeleton";
import { cn } from "@/lib/utils";
import { StatusBadge } from "@/pages/Encounters/EncounterProperties";
import { formatDateTime } from "@/Utils/utils";

import {
  ENCOUNTER_PRIORITY_COLORS,
  EncounterRead,
} from "@/types/emr/encounter/encounter";

interface Props {
  encounter?: EncounterRead;
  isLoading: boolean;
  isHistorical: boolean;
  onReturnToCurrent: () => void;
  editUrl?: string;
}

export default function EncounterDetailsHeader({
  encounter,
  isLoading,
  isHistorical,
  onReturnToCurrent,
  editUrl,
}: Props) {
  const { t } = useTranslation();
  const periodLabel = encounter
    ? [
        encounter.period.start
          ? format(new Date(encounter.period.start), "dd MMM yyyy")
          : "--",
        encounter.period.end
          ? format(new Date(encounter.period.end), "dd MMM yyyy")
          : t("ongoing"),
      ].join(" – ")
    : "";

  return (
    <section
      aria-label={t("encounter")}
      onKeyDown={(event) => {
        if (
          event.key === "Enter" &&
          !event.shiftKey &&
          !event.ctrlKey &&
          !event.metaKey &&
          !event.altKey
        ) {
          // Preserve native activation despite the global Enter shortcut.
          event.stopPropagation();
        }
      }}
      className={cn(
        "rounded-xl border px-3 py-2.5 sm:px-4",
        isHistorical
          ? "border-amber-300 bg-amber-50"
          : "border-gray-200 bg-white",
      )}
    >
      {isHistorical && (
        <div className="mb-2 flex flex-wrap items-center justify-between gap-2 border-b border-amber-200 pb-2">
          <span
            role="status"
            className="flex items-center gap-2 text-sm font-semibold text-amber-900"
          >
            <History aria-hidden="true" className="size-4 shrink-0" />
            {t("viewing_another_encounter")}
          </span>
          <Button
            type="button"
            variant="outline"
            className="h-8 border-amber-300 bg-white px-2.5 text-xs text-amber-950 shadow-xs hover:border-amber-400 hover:bg-amber-100"
            onClick={onReturnToCurrent}
          >
            <ArrowLeft aria-hidden="true" />
            {t("back_to_current_encounter")}
          </Button>
        </div>
      )}
      {isLoading ? (
        <Skeleton className="h-9 w-full max-w-md" />
      ) : encounter ? (
        <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
          <span
            aria-hidden="true"
            className={cn(
              "flex size-8 shrink-0 items-center justify-center rounded-lg text-xs font-bold",
              isHistorical
                ? "bg-amber-100 text-amber-800"
                : "bg-primary-50 text-primary-700",
            )}
          >
            {t(`encounter_class_short__${encounter.encounter_class}`)}
          </span>
          <span className="text-base font-semibold text-gray-950">
            {t(`encounter_class__${encounter.encounter_class}`)}
          </span>
          <div className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-1 text-[15px] text-gray-600">
            <span className="wrap-anywhere">{encounter.facility.name}</span>
            {encounter.current_location && (
              <>
                <span aria-hidden="true" className="text-gray-300">
                  ·
                </span>
                <span className="wrap-anywhere">
                  {encounter.current_location.name}
                </span>
              </>
            )}
            <span aria-hidden="true" className="h-5 w-px bg-gray-300" />
            <Popover>
              <PopoverTrigger asChild>
                <button
                  type="button"
                  aria-label={`${t("encounter_dates")}: ${periodLabel}`}
                  className="rounded-sm text-left underline-offset-4 hover:underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-gray-500"
                >
                  {periodLabel}
                </button>
              </PopoverTrigger>
              <PopoverContent
                align="start"
                className="w-auto max-w-[calc(100vw-2rem)]"
              >
                <dl className="space-y-3 text-sm">
                  <div>
                    <dt className="text-gray-500">{t("start_date")}</dt>
                    <dd className="font-medium text-gray-950">
                      {encounter.period.start
                        ? formatDateTime(encounter.period.start)
                        : "--"}
                    </dd>
                  </div>
                  <div>
                    <dt className="text-gray-500">{t("end_date")}</dt>
                    <dd className="font-medium text-gray-950">
                      {encounter.period.end
                        ? formatDateTime(encounter.period.end)
                        : t("ongoing")}
                    </dd>
                  </div>
                </dl>
              </PopoverContent>
            </Popover>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <StatusBadge encounter={encounter} />
            <Badge
              variant={ENCOUNTER_PRIORITY_COLORS[encounter.priority]}
              className="min-h-7 px-2"
            >
              {t(`encounter_priority__${encounter.priority}`)}
            </Badge>
            {editUrl && (
              <Button
                variant="ghost"
                size="icon"
                className="size-8 shrink-0 text-gray-950"
                asChild
              >
                <Link
                  href={editUrl}
                  aria-label={t("update_encounter")}
                  title={t("update_encounter")}
                  data-shortcut-id="update-encounter"
                >
                  <SquarePen
                    aria-hidden="true"
                    className="size-4"
                    strokeWidth={1.75}
                  />
                </Link>
              </Button>
            )}
          </div>
        </div>
      ) : null}
    </section>
  );
}
import query from "@/Utils/request/query";
import { formatName } from "@/Utils/utils";
import TagBadge from "@/components/Tags/TagBadge";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { useEncounter } from "@/pages/Encounters/utils/EncounterProvider";
import {
  AccountBillingStatus,
  AccountStatus,
} from "@/types/billing/account/Account";
import accountApi from "@/types/billing/account/accountApi";
import { useQuery } from "@tanstack/react-query";
import { useState } from "react";
import { useTranslation } from "react-i18next";

export const SummaryPanelEncounterDetails = () => {
  const { t } = useTranslation();
  const [showAllCareTeam, setShowAllCareTeam] = useState(false);
  const {
    selectedEncounter: encounter,
    patientId,
    facilityId,
  } = useEncounter();
  const { data: account } = useQuery({
    queryKey: ["accounts", patientId],
    queryFn: query(accountApi.listAccount, {
      pathParams: { facilityId: facilityId || "" },
      queryParams: {
        patient: patientId,
        status: AccountStatus.active,
        billing_status: AccountBillingStatus.open,
        limit: 1,
      },
    }),
    enabled: !!facilityId,
  });

  if (!encounter) return null;

  return (
    <div className="grid gap-4 rounded-xl border border-gray-200 bg-white p-3 sm:grid-cols-2 xl:hidden">
      <div className="flex min-w-0 flex-col gap-4 sm:border-r sm:border-gray-200 sm:pr-4">
        <div>
          <span className="text-sm font-medium text-gray-700">
            {t("dep_and_teams")}:
          </span>
          <div className="flex flex-wrap gap-2">
            {encounter.organizations.length > 0 ? (
              encounter.organizations.map((org) => (
                <Badge key={org.id} variant="blue" className="capitalize">
                  {org.name}
                </Badge>
              ))
            ) : (
              <span>--</span>
            )}
          </div>
        </div>
        <div>
          <span className="text-sm font-medium text-gray-700">
            {t("encounter_tags")}:
          </span>
          <div className="flex flex-wrap gap-2">
            {encounter.tags.length > 0 ? (
              encounter.tags.map((tag) => <TagBadge key={tag.id} tag={tag} />)
            ) : (
              <p className="text-sm text-gray-500">{t("no_tags")}</p>
            )}
          </div>
        </div>
        {encounter.hospitalization?.re_admission && (
          <div>
            <span className="text-sm font-medium text-gray-700">
              {t("hospitalisation")}:
            </span>
            <div>
              <Badge variant="blue">{t("re_admission")}</Badge>
            </div>
          </div>
        )}
      </div>
      <div className="flex min-w-0 flex-col gap-4">
        <div className="flex flex-col">
          <span className="text-sm font-medium text-gray-700">
            {t("account")}:
          </span>
          <div className="text-sm font-semibold text-gray-950">
            {account?.results[0]?.name || "--"}
          </div>
        </div>
        {encounter.care_team.length > 0 && (
          <div className="flex flex-col gap-2">
            <span className="text-sm font-medium text-gray-700">
              {t("care_team")}:
            </span>
            <div className="flex flex-wrap items-center gap-2">
              {(showAllCareTeam
                ? encounter.care_team
                : encounter.care_team.slice(0, 2)
              ).map((member) => (
                <div
                  key={member.member.id}
                  className="flex flex-col rounded-lg border border-gray-200 bg-gray-100 px-2 py-1"
                >
                  <span className="text-sm font-medium text-gray-950 md:text-base">
                    {formatName(member.member)}
                  </span>
                  <span className="text-xs text-gray-600 md:text-sm">
                    {member.role.display}
                  </span>
                </div>
              ))}
              {encounter.care_team.length > 2 && (
                <Button
                  type="button"
                  onClick={() => setShowAllCareTeam(!showAllCareTeam)}
                  variant="link"
                  size="xs"
                  className="underline"
                >
                  {showAllCareTeam
                    ? t("show_less")
                    : `+${encounter.care_team.length - 2} ${t("more")}`}
                </Button>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};
import { ChevronDown } from "lucide-react";
import React from "react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
