  return (
    <Badge
      variant={ENCOUNTER_CLASSES_COLORS[encounter.encounter_class]}
      size="sm"
    >
      <ClassIcon className="size-3" />
      {t(`encounter_class__${encounter.encounter_class}`)}
    </Badge>
  );
};
